import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Security advanced II testing — v0.2 8 axis × 4 provider = 32 cell advanced grid + real-driver env-gate (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/security-advanced-II-testing.md","filePath":"concepts/security-advanced-II-testing.md"}'),i={name:"concepts/security-advanced-II-testing.md"};function r(s,e,c,n,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="security-advanced-ii-testing-—-v0-2-8-axis-×-4-provider-32-cell-advanced-grid-real-driver-env-gate-ssot" tabindex="-1">Security advanced II testing — v0.2 8 axis × 4 provider = 32 cell advanced grid + real-driver env-gate (SSOT) <a class="header-anchor" href="#security-advanced-ii-testing-—-v0-2-8-axis-×-4-provider-32-cell-advanced-grid-real-driver-env-gate-ssot" aria-label="Permalink to &quot;Security advanced II testing — v0.2 8 axis × 4 provider = 32 cell advanced grid + real-driver env-gate (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.39-1 security v0.2 package (<code>@kiwa-test/security</code> v0.2.0) covers <strong>8 advanced axes</strong> that model the deepening security posture of a real production stack beyond the v0.1 base HTTP-header + policy-engine surface — mTLS handshake + zero-trust access + SIEM audit + incident response + cryptography advanced + container / Kubernetes hardening + supply chain SLSA + web vitals security. This concept doc is the SSOT for those 8 advanced axes; the tutorials (82-84) and dogfood apps (v1.39-2/3/4) are the concrete implementations.</p><p>The v0.2 grid is orthogonal to the v0.1 base grid — the base grid (<code>SECURITY_FIDELITY_GRID</code>) covers the &quot;read a request, decide allow / deny, emit audit event&quot; primitive across 4 provider (<code>helmet</code> / <code>express-rate-limit</code> / <code>casbin</code> / <code>coraza</code>), and the advanced grid (<code>SECURITY_ADV_FIDELITY_GRID</code>) covers the &quot;service mesh + policy engine + SIEM + secrets vault&quot; primitives across a different 4 provider (<code>istio</code> / <code>opa</code> / <code>siem-splunk</code> / <code>vault</code>). Read the <code>security-real-driver-testing.md</code> concept doc first for the v0.1 base grid, then read this doc for the v0.2 advanced grid.</p><h2 id="the-8-advanced-axes-grid" tabindex="-1">The 8 advanced axes grid <a class="header-anchor" href="#the-8-advanced-axes-grid" aria-label="Permalink to &quot;The 8 advanced axes grid&quot;">​</a></h2><p>The 8 axes are cover-oriented — each one names a real-world failure surface every non-trivial production security stack hits after the base v0.1 axes land.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Real-world failure it catches</th><th>v0.2 API</th></tr></thead><tbody><tr><td>mTLS</td><td>&quot;The OCSP staple was missing but the handshake still completed because the middleware treated <code>stapled: false</code> as <code>unknown</code> instead of <code>deny</code>&quot; (no fail-closed staple check, no SPKI-only pinning that survives cert rotation, no SCT-count guard)</td><td><code>startMtlsSession</code> / <code>completeHandshake</code> / <code>verifyPin</code> / <code>verifyOcsp</code> / <code>checkCtLog</code></td></tr><tr><td>Zero-trust</td><td>&quot;The user&#39;s laptop had no disk encryption but the JIT role grant fired because the posture check ran on a stale cache&quot; (no 4-signal posture check, no 0-100 risk score, no 50-threshold JIT gate, no allowlist micro-segmentation)</td><td><code>startZeroTrustSession</code> / <code>evaluatePosture</code> / <code>scoreRisk</code> / <code>requestJit</code> / <code>enforceMicroSegment</code></td></tr><tr><td>SIEM audit</td><td>&quot;The SIEM ingested the raw event but the correlation rule never fired because the retention step was skipped and the event id was missing from the correlation set&quot; (no Splunk-CIM shape, no tamper-evident seal chain, no hot / warm / cold retention, no all-required correlation rule)</td><td><code>startSiemAuditSession</code> / <code>structureEvent</code> / <code>sealEvents</code> / <code>applyRetention</code> / <code>correlate</code></td></tr><tr><td>Incident response</td><td>&quot;The post-mortem said <code>oops, we restarted the service</code> and shipped as-is because the harness never enforced a root-cause floor or an action-item minimum&quot; (no 5-tier severity, no channel + primary on-call check, no artifact-size record, no root-cause 10-char floor)</td><td><code>startIncidentSession</code> / <code>triggerPlaybook</code> / <code>classifySeverity</code> / <code>escalate</code> / <code>captureForensics</code> / <code>recordPostMortem</code></td></tr><tr><td>Cryptography advanced</td><td>&quot;The envelope-encrypted key rotated but the KDF derived the same key material because the nonce reuse was not caught, and the AEAD sealed a payload with a stale key without a rotation event&quot; (no AEAD nonce-reuse guard, no KDF salt uniqueness, no envelope key rotation, no HSM sign path, no post-quantum KEM)</td><td><code>startCryptoSession</code> / <code>sealAead</code> / <code>deriveKey</code> / <code>wrapEnvelope</code> / <code>rotateKey</code> / <code>signWithHsm</code> / <code>encapsulatePq</code></td></tr><tr><td>Container / K8s</td><td>&quot;The pod ran as root because the Pod Security Standard was <code>baseline</code> instead of <code>restricted</code>, and the network policy skipped the workload namespace&quot; (no pod-security enforcement, no network policy allowlist, no admission-controller deny path)</td><td><code>startK8sSession</code> / <code>enforcePodSecurity</code> / <code>applyNetworkPolicy</code> / <code>decideAdmission</code></td></tr><tr><td>Supply chain</td><td>&quot;The build claimed SLSA 3 but the isolation signal was false and the CI operator only noticed after a downstream consumer rejected the attestation&quot; (no 8-signal SLSA level classifier, no reproducible-build hash match, no builder-id + materials-count provenance, no 1+ valid-signature attestation check)</td><td><code>startSupplyChainSession</code> / <code>verifySlsaLevel</code> / <code>matchReproducibleBuild</code> / <code>signProvenance</code> / <code>verifyAttestation</code></td></tr><tr><td>Web Vitals security</td><td>&quot;The subresource-integrity hash was set but the trusted-types policy was missing, and the permissions policy allowed <code>microphone</code> in an iframe that had no need for it&quot; (no SRI hash verify, no trusted-types enforce, no permissions-policy allowlist, no cross-origin isolation <code>same-origin</code> gate)</td><td><code>startWvsSession</code> / <code>verifySri</code> / <code>enforceTrustedTypes</code> / <code>applyPermissionsPolicy</code> / <code>enforceCrossOriginIsolation</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + real Istio / OPA / Splunk HEC / Vault, seconds scale), and a fidelity assertion that the two produce the same output. Tutorial 82 covers the mTLS + zero-trust chain end-to-end (handshake → pin → OCSP → CT → posture → risk → JIT → segment), tutorial 83 covers the SIEM audit + incident response chain (structure → seal → retention → correlate → playbook → severity → escalate → forensics → post-mortem), tutorial 84 covers the supply chain SLSA chain (level → reproducible → provenance → attestation). The remaining 3 axes (cryptography advanced, container / K8s, web vitals security) have full API coverage in v1.39-1 and dedicated tutorial coverage in a later milestone.</p><h2 id="the-4-provider-×-8-axis-32-cell-grid" tabindex="-1">The 4-provider × 8-axis = 32 cell grid <a class="header-anchor" href="#the-4-provider-×-8-axis-32-cell-grid" aria-label="Permalink to &quot;The 4-provider × 8-axis = 32 cell grid&quot;">​</a></h2><p>Every provider covers every axis. The mock shapes are provider-neutral (the API surface is the same across istio + opa + siem-splunk + vault), the emitted event dialects are provider-specific (<code>istio.mtls.handshake</code> vs. <code>opa.mtls.handshake</code> vs. <code>splunk.mtls.handshake</code> vs. <code>vault.mtls.handshake</code>), and the advanced fidelity harness reports the coverage explicitly through <code>SECURITY_ADV_FIDELITY_GRID</code>.</p><table tabindex="0"><thead><tr><th>Provider</th><th>mTLS</th><th>Zero-trust</th><th>SIEM audit</th><th>Incident resp</th><th>Crypto adv</th><th>Container / K8s</th><th>Supply chain</th><th>Web Vitals sec</th></tr></thead><tbody><tr><td>istio</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>opa</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>siem-splunk</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>vault</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p>The v0.2 advanced grid is fully covered — every provider implements every axis because the semantics are runtime-agnostic. That is what makes cross-provider reuse (a policy that runs under istio + opa + splunk + vault without change) even possible. The neutral event names live in the v0.2 <code>types.ts</code> SSOT and the per-provider dialect table is a static lookup — a new provider drops into the same shape.</p><h3 id="why-the-advanced-grid-is-fully-covered" tabindex="-1">Why the advanced grid is fully covered <a class="header-anchor" href="#why-the-advanced-grid-is-fully-covered" aria-label="Permalink to &quot;Why the advanced grid is fully covered&quot;">​</a></h3><p>istio + opa + siem-splunk + vault converged on the same neutral events at the &quot;operate on a security signal, decide an outcome, emit an audit event&quot; primitive — the &quot;advanced security policy over a service-mesh + policy-engine + SIEM + secrets-vault stack&quot; shape is the same across all 4 providers, even though the wire encodings differ (sidecar-injected mTLS vs. rego evaluation vs. HEC event ingest vs. transit engine call). The <code>providerAdvEventName(target, neutralEvent)</code> mapping table is the single point where the 4 dialects diverge; everything upstream stays neutral. The v1.39 advanced fidelity grid at 32/32 = 100 % implemented reflects that convergence at the &quot;advanced security decision&quot; level.</p><h2 id="the-kiwa-mode-real-env-gate-contract-for-the-advanced-grid" tabindex="-1">The <code>KIWA_MODE=real</code> env-gate contract for the advanced grid <a class="header-anchor" href="#the-kiwa-mode-real-env-gate-contract-for-the-advanced-grid" aria-label="Permalink to &quot;The `KIWA_MODE=real` env-gate contract for the advanced grid&quot;">​</a></h2><p><code>skipUnlessAdvReal(provider, env)</code> returns <code>{ skip: false, reason: &#39;KIWA_MODE=real + required env present — real driver&#39; }</code> when <code>env.KIWA_MODE === &#39;real&#39;</code> and the required env for that provider is set, and <code>{ skip: true, reason: &#39;KIWA_MODE!=real (got &quot;unset&quot;) — mock driver&#39; }</code> otherwise. A test that respects the contract combines the gate with a required-env presence check — the dogfood apps use this at each <code>describe.skipIf(gate.skip)</code> block.</p><p>Per-provider required-env mapping (<code>ADV_REQUIRED_KEYS</code>).</p><ul><li><strong>istio</strong> → <code>KIWA_MODE</code> + <code>KIWA_ISTIO_URL</code> (Istio control plane / pilot; <code>KIWA_ISTIO_TOKEN</code> optional bearer)</li><li><strong>opa</strong> → <code>KIWA_MODE</code> + <code>KIWA_OPA_URL</code> (OPA data API endpoint; <code>KIWA_OPA_TOKEN</code> optional bearer)</li><li><strong>siem-splunk</strong> → <code>KIWA_MODE</code> + <code>KIWA_SPLUNK_HEC_URL</code> + <code>KIWA_SPLUNK_HEC_TOKEN</code> (Splunk HEC ingest endpoint + HEC token)</li><li><strong>vault</strong> → <code>KIWA_MODE</code> + <code>KIWA_VAULT_URL</code> + <code>KIWA_VAULT_TOKEN</code> (HashiCorp Vault API endpoint + auth token)</li></ul><p>A test that respects the contract runs the mock path unconditionally and the real-driver path only when both <code>KIWA_MODE=real</code> and the required env are present. That means CI stays cheap by default (mock only, ms scale), the nightly job flips <code>KIWA_MODE=real</code> + the required <code>_URL</code> / <code>_TOKEN</code> envs, and the fidelity harness ties the two together.</p><p>Absent env means silently fall back to mock mode — the test still runs, the real-driver assertions get skipped. Absent <code>KIWA_MODE</code> means fall back to mock. An invalid <code>KIWA_MODE</code> value (anything other than <code>real</code>) also falls back to mock so a typo does not break tests.</p><h2 id="the-dogfood-app-new-pattern" tabindex="-1">The dogfood app new pattern <a class="header-anchor" href="#the-dogfood-app-new-pattern" aria-label="Permalink to &quot;The dogfood app new pattern&quot;">​</a></h2><p>The 3 dogfood apps (v1.39-2/3/4) each expose a <code>pnpm test</code> command that keeps the mock-only path green sub-second, and are wired for <code>pnpm test:real</code> follow-up phases when the required envs are present.</p><ul><li><code>examples/dogfood-security-mtls-zero-trust-app</code> — Istio mTLS + certificate pinning + OCSP stapling + CT log + OPA zero-trust posture + risk score + JIT + micro-segmentation + <code>pnpm test:real</code> that walks the mTLS + zero-trust chain against a real Istio sidecar + OPA data API. 74 test.</li><li><code>examples/dogfood-security-siem-incident-app</code> — Splunk HEC structured logging + tamper-evident seal + retention + correlation + Vault-backed incident response playbook + severity + escalation + forensics + post-mortem + orchestrator + <code>pnpm test:real</code> that walks the SIEM + IR chain against a real Splunk HEC + Vault backend. 85 test.</li><li><code>examples/dogfood-security-supply-chain-slsa-app</code> — sigstore + in-toto SLSA level + reproducible build + signed provenance + attestation + <code>pnpm test:real</code> that walks the supply chain against a real sigstore + in-toto attestation engine. 76 test.</li></ul><p>The pattern each new app follows.</p><ol><li>Keep the mock-only path (<code>pnpm test</code>) green — the fast inner loop stays sub-second.</li><li>Add a <code>pnpm test:e2e</code> command that spins the docker-compose stack (Istio sidecar + OPA data API + Splunk HEC + Vault, subset per app) and walks the real security policy flow.</li><li>Add a <code>pnpm test:real</code> command that requires the axis-specific <code>_URL</code> / <code>_TOKEN</code> env(s) and routes through the real provider endpoint.</li><li>Run the same fidelity-harness assertions against the real driver; failure means &quot;the mock diverged from real provider behavior&quot; — the mock gets the fix.</li><li>Emit a <code>quality-report/fidelity-latest.md</code> + <code>.json</code> that the v1.29 3-layer defensive structure (release-invariants + docs-e2e + release-smoke) picks up on merge.</li></ol><h2 id="the-not-implemented-failure-mode" tabindex="-1">The <code>not-implemented</code> failure mode <a class="header-anchor" href="#the-not-implemented-failure-mode" aria-label="Permalink to &quot;The `not-implemented` failure mode&quot;">​</a></h2><p>If the advanced fidelity harness has a <code>planned</code> cell, the corresponding tutorial + dogfood + snippet-validation-test trio does not exist yet. The 32-cell advanced grid at v1.39 has 0 <code>planned</code> cells — every intended cell is <code>implemented</code>. When a future milestone adds a 9th advanced axis (e.g., <code>confidential-computing-tee</code> or <code>runtime-app-self-protection</code>), it will start as <code>planned</code> for all 4 providers, then transition to <code>implemented</code> for the ones that cover it as the milestone lands its tutorial + dogfood + snippet test.</p><h2 id="how-this-ties-into-the-13-axis-release-gate" tabindex="-1">How this ties into the 13-axis release gate <a class="header-anchor" href="#how-this-ties-into-the-13-axis-release-gate" aria-label="Permalink to &quot;How this ties into the 13-axis release gate&quot;">​</a></h2><p>v1.39 does not add a 14th release-gate axis. The 8 advanced security axes gate the security package&#39;s own tests (via <code>pnpm --filter @kiwa-test/security test</code>) but do not surface as a per-package <code>@kiwa-test/quality-metrics</code> axis. The reasoning — the advanced fidelity harness is provider-shape-specific, and a package that does not export to istio / opa / splunk / vault has nothing to assert on. When a future milestone adds a <code>security.advanced.fidelity</code> axis that describes &quot;which advanced security providers this package&#39;s tests hit,&quot; it will slot into the 13-axis release gate as the 14th; v1.39 keeps the axis count at 13.</p><h2 id="the-v0-1-→-v0-2-pair-深化-relationship" tabindex="-1">The v0.1 → v0.2 pair 深化 relationship <a class="header-anchor" href="#the-v0-1-→-v0-2-pair-深化-relationship" aria-label="Permalink to &quot;The v0.1 → v0.2 pair 深化 relationship&quot;">​</a></h2><p>v1.39 is the 9th pair 2 段拡張 in kiwa&#39;s 縦深化 progression. The v0.1 base grid + the v0.2 advanced grid together form a full &quot;security posture at the HTTP request layer + service mesh + policy engine + SIEM + secrets vault&quot; coverage — the base grid covers the request-time decision layer (CSP / rate limit / authorization / WAF / threat model / secrets scan / SBOM / security headers), and the advanced grid covers the &quot;beyond request time&quot; layers (mTLS / zero-trust / SIEM / IR / crypto / K8s / supply chain / web vitals security). A production stack usually adopts the base grid first (fast to land, low blast radius) and layers the advanced grid on top as the stack matures.</p><p>Naming convention — the base grid uses &quot;security&quot; as the axis prefix (<code>csp</code> / <code>rate-limit</code> / <code>authorization</code> / <code>waf</code> / <code>threat-model</code> / <code>secrets-scan</code> / <code>sbom</code> / <code>security-headers</code>), and the advanced grid uses topic prefixes (<code>mtls</code> / <code>zero-trust</code> / <code>siem-audit</code> / <code>incident-response</code> / <code>crypto-advanced</code> / <code>container-k8s</code> / <code>supply-chain</code> / <code>web-vitals-security</code>). The two prefix families do not collide, so a downstream consumer can pick both grids without renaming.</p><h2 id="ssot-boundaries" tabindex="-1">SSOT boundaries <a class="header-anchor" href="#ssot-boundaries" aria-label="Permalink to &quot;SSOT boundaries&quot;">​</a></h2><ul><li>The 8 advanced security axes live in this doc. Tutorials 82-84 and the migration guide (v1.38 → v1.39) link back here for the axis SSOT.</li><li>The v0.1 base security axes live in <code>security-real-driver-testing.md</code> (v1.37). This doc does not restate the v0.1 axes — read that doc first if you have not already onboarded the v0.1 base grid.</li><li>The <code>KIWA_MODE=real</code> env-gate contract lives in the <code>real-driver-testing.md</code> general concept doc. This doc does not restate the general contract, only the per-advanced-provider mapping (<code>ADV_ENDPOINT_ENV_KEY</code> + <code>ADV_API_KEY_ENV_KEY</code> + <code>ADV_REQUIRED_KEYS</code>).</li><li>The fidelity harness that ties the mock output back to the real driver output lives in the <code>payment-real-driver-testing.md</code> / <code>frontend-real-driver-testing.md</code> / <code>observability-real-driver-testing.md</code> / <code>search-real-driver-testing.md</code> / <code>security-real-driver-testing.md</code> / <code>ai-llm-real-driver-testing.md</code> concept docs (per milestone). The advanced grid uses the same harness shape as the base grid; the only differences are the provider set and the axis prefix family.</li></ul>',33)])])}const v=t(i,[["render",r]]);export{u as __pageData,v as default};
